import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"UIX tablet soak: 720 Cards","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/atlas/tablet-uix-dauertest.md","filePath":"en/projects/atlas/tablet-uix-dauertest.md","lastUpdated":1792851046000}'),s={name:"en/projects/atlas/tablet-uix-dauertest.md"};function n(i,e,l,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="uix-tablet-soak-720-cards" tabindex="-1">UIX tablet soak: 720 Cards <a class="header-anchor" href="#uix-tablet-soak-720-cards" aria-label="Permalink to &quot;UIX tablet soak: 720 Cards&quot;">​</a></h1><p>As of 19 October 2026. <strong>User confirms 60 minutes on each host, .177 and .68, with working theme changes and reconnection.</strong> App 0.1.327, HA 2026.10.2, UIX 8.4.0; Card-Mod is not loaded. User-reported device: Samsung Galaxy Tab A6, Android 11 / LineageOS, Chrome Mobile 155.</p><p>Fresh full backups and existing-data captures precede setup. Owned dashboards are sidebar-visible without Admin-only; existing Editors, projects, plugins and settings are preserved.</p><p>This is user-reported functional qualification. No separately collected tablet JSON logs, FPS/memory measurements or detailed rotation/scrolling results are supplied. Desktop preflight and local simulation remain separate.</p><h2 id="historical-procedure" tabindex="-1">Historical procedure <a class="header-anchor" href="#historical-procedure" aria-label="Permalink to &quot;Historical procedure&quot;">​</a></h2><p>Run a complete 60 minutes per host, sequentially:</p><p>Owned views at <code>/atlas-tablet-uix-soak-20261019/720</code> are removed after completion and are no longer active test links. Prepare new backups and owned views before any future repeat.</p><ol><li>Connect power, keep the screen awake and close other Apps as in the earlier test. Keep only the current test page in the foreground. Sign in yourself with the existing HA account; do not share credentials.</li><li>Check “HA verbunden”, then press <strong>60 Minuten starten</strong> once. Verify the timer advances; do not reload or leave the dashboard view.</li><li>Every ten minutes alternate portrait/landscape and scroll down/back. Look for stalls, overlaps, clipped text and error Cards. Mushroom text/icon/color change with the synthetic state.</li><li>The helper toggles 18/28 approximately every ten seconds, light/dark at minutes 10/20/30/40/50 and reconnects at 15/30/45. Brief disconnection is expected, followed by “HA verbunden”. Do not reload.</li><li>At <strong>60 Minuten beendet</strong>, record the result. <strong>Ergebnis markieren</strong> selects the local JSON for normal copying. If awkward on the tablet, first report host, final time, reconnection count and observed errors.</li><li>Repeat on the second host. If stalled or persistently disconnected, use <strong>Stoppen / Theme zurück</strong> and report how long it ran.</li></ol><p>Only owned synthetic states change; no real device is controlled. Timer gaps and HA request times do not measure FPS/rendering latency. Report screen sleep or background pauses as interruptions. Finish/Stop restores the original theme. Reload does not automatically resume the run.</p><h2 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h2><p>Owned dashboards, resources, synthetic states and temporary UIX are removed; WWW files are in recoverable File Studio Trash. All seven projects and six plugins per host, 551 captured existing files on .177 and nine on .68, original settings and old trash entries are unchanged. Three full backups remain per host. PC backups and installed updates are preserved. Never load Card-Mod and UIX together.</p>',11)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
